package com.lmspilot.identity.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.*; @Entity @Table(name="password_history",indexes=@Index(name="idx_password_history_user",columnList="user_id,created_at")) public class PasswordHistoryEntity { @Id public UUID id=UUID.randomUUID(); @Column(name="user_id",nullable=false) public UUID userId; @Column(name="password_hash",nullable=false,length=255) public String passwordHash=""; @Column(name="created_at",nullable=false) public Instant createdAt=Instant.now(); public PasswordHistoryEntity(){} }
